# import necessary libraries
import math

def prime_factors(n):
    factors = []
    # divide n by 2 until n is odd
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # for odd factors from 3 to sqrt(n)
    for i in range(3, int(math.sqrt(n))+1, 2):
        while n % i == 0:
            if i not in factors:
                factors.append(i)
            n = n // i
    # if n is a prime number and greater than 2
    if n > 2:
        factors.append(n)
    return factors

# let's test the factors function
