    def __init__(self, name, age):
        self.name = name
        self.age = age

    def serialize(self):
        return json.dumps({
            'name': self.name,
            'age': self.age
        })

    @classmethod
    def deserialize(cls, serialized_obj):
        obj = json.loads(serialized_obj)
        return cls(obj['name'], obj['age'])

